@import "tailwindcss";

:root {
  --background: #3E000C;
  --foreground: #FFECD1;
  --card: #551C24;
  --border: #6E3B3D;
  --muted: #A88278;
  --accent: #FFECD1;
  --accent-hover: #FFF5E5;
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-border: var(--border);
  --color-muted: var(--muted);
  --color-accent: var(--accent);
  --color-accent-hover: var(--accent-hover);
  --font-sans: var(--font-dm-sans);
  --font-heading: var(--font-space-grotesk);
}

html {
  scroll-behavior: auto;
}

html.lenis, html.lenis body {
  height: auto;
}

.lenis.lenis-smooth {
  scroll-behavior: auto;
}

.lenis.lenis-smooth [data-lenis-prevent] {
  overscroll-behavior: contain;
}

.lenis.lenis-stopped {
  overflow: hidden;
}

body {
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-dm-sans), sans-serif;
  overflow-x: hidden;
}

::selection {
  background-color: #FFECD1;
  color: #3E000C;
}

/* Gradient text — warm sand shimmer */
.gradient-text {
  background: linear-gradient(135deg, #FFECD1 0%, #A88278 50%, #FFECD1 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* Custom scrollbar */
::-webkit-scrollbar {
  width: 6px;
}

::-webkit-scrollbar-track {
  background: #3E000C;
}

::-webkit-scrollbar-thumb {
  background: #6E3B3D;
  border-radius: 3px;
}

::-webkit-scrollbar-thumb:hover {
  background: #8A5050;
}

/* Grid background */
.grid-bg {
  background-image:
    linear-gradient(rgba(110, 59, 61, 0.3) 1px, transparent 1px),
    linear-gradient(90deg, rgba(110, 59, 61, 0.3) 1px, transparent 1px);
  background-size: 60px 60px;
}

/* Card hover lift */
.card-hover {
  transition: transform 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94),
              border-color 0.3s ease,
              box-shadow 0.3s ease;
}

@media (hover: hover) {
  .card-hover:hover {
    transform: translateY(-4px);
    box-shadow: 0 12px 40px rgba(0, 0, 0, 0.4);
  }
}

/* Section divider */
.section-divider {
  height: 1px;
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(255, 236, 209, 0.08) 25%,
    rgba(255, 236, 209, 0.15) 50%,
    rgba(255, 236, 209, 0.08) 75%,
    transparent 100%
  );
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  .card-hover:hover {
    transform: none;
  }
}

